// Convierte los adjuntos (binarios) en lotes de hasta 5 documentos para Nokfi.
const TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const docs = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  for (const [key, bin] of Object.entries(item.binary || {})) {
    if (!TYPES.includes(bin.mimeType)) continue;
    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    docs.push({ name: bin.fileName || key, mime: bin.mimeType, data: buffer.toString('base64') });
  }
}
const batches = [];
for (let k = 0; k < docs.length; k += 5) batches.push({ json: { files: docs.slice(k, k + 5) } });
return batches;

// Resumen del mes con las cifras de Nokfi (sumadas aquí, no por la IA).
const invs = $input.all().flatMap(i => i.json.invoices || []);
const errors = $input.all().flatMap(i => i.json.errors || []);
const sum = (k) => invs.reduce((s, x) => s + (Number(x[k]) || 0), 0);
const eur = (n) => n.toLocaleString('es-ES', { style: 'currency', currency: 'EUR', useGrouping: 'always' });
const bad = invs.filter(x => !x.checks.totals_ok || !x.checks.nif_valid || !x.checks.date_valid);
const lines = [
  `Facturas leídas: ${invs.length}`,
  `Base imponible: ${eur(sum('base'))}`, `IVA: ${eur(sum('vat_amount'))}`, `Retenciones: ${eur(sum('irpf_amount'))}`, `Total: ${eur(sum('total'))}`,
  '', bad.length ? `Revisa ${bad.length} factura(s):` : 'Todas las facturas cuadran.',
  ...bad.map(x => `- ${x.file_name}: ${(x.warnings || []).map(w => w.message).join('; ')}`),
  ...(errors.length ? ['', 'No se pudieron leer:', ...errors.map(e => `- ${e.file_name}: ${e.message}`)] : [])
];
return [{ json: { subject: `Resumen de facturas · ${new Date().toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}`, text: lines.join('\n') } }];
